    public func executeExitActions(_ state: StaticOptionalState, engine: Engine<StaticOptionalPolicy>, configurationBeforeExit: [StaticOptionalState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: StaticOptionalState,
        event: StaticOptionalEvent,
        engine: Engine<StaticOptionalPolicy>
    ) -> EnabledTransition<StaticOptionalState>? {
        switch state {
        case .tracking:
            if event == .dueSet {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .dueClear {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .dueRead {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 2,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .dueFallback {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 3,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .relay {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 4,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .dueSent {
                // W3C SCXML 5.9: cond="_event.data.due !== null" lowered to Swift at build time
                if (self.pendingPayloadTag == .dueSent && (self.pendingDueSentPayload.due != nil)) {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 5,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .dueSent {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 6,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .errorExecution {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 7,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .finish {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.done)],
                        transitionIndex: 8,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

    /// Runs one transition's executable content (W3C SCXML 3.13), between the
    /// microstep's exits and its entries.
    public func executeTransitionContent(source: StaticOptionalState, transitionIndex: Int, engine: Engine<StaticOptionalPolicy>) {
        switch source {
        case .tracking:
            switch transitionIndex {
            case 0:
                // W3C SCXML 4.9: a transition's content is one block; an error ends it.
                sceBlock: do {
                    if pendingPayloadTag != .dueSet {
                        break sceBlock
                    }


                self.vDue = self.pendingDueSetPayload.due



                if ({ () -> Bool in let sceFailure = Failure(); let sceValue = (self.pendingDueSetPayload.title).map { (scePresent) in Checked.bounded(sceFailure, scePresent, capacity: 16) }; if sceFailure.failed { engine.raise(EventWithMetadata.platformError(StaticOptionalEvent.errorExecution, message: "<assign location='title'>: an integer operation overflowed or failed")); return true }; self.vTitle = sceValue; return false }()) {
                    break sceBlock  // W3C SCXML 4.9: the error ends the block
                }



                self.vStatus = self.pendingDueSetPayload.status



                if ({ () -> Bool in let sceFailure = Failure(); let sceValue = StaticOptionalDueRecord(id: self.pendingDueSetPayload.id, due: self.pendingDueSetPayload.due, title: (self.pendingDueSetPayload.title).map { (scePresent) in Checked.bounded(sceFailure, scePresent, capacity: 16) }, status: self.pendingDueSetPayload.status); if sceFailure.failed { engine.raise(EventWithMetadata.platformError(StaticOptionalEvent.errorExecution, message: "<assign location='item'>: an integer operation overflowed or failed")); return true }; self.vItem = sceValue; return false }()) {
                    break sceBlock  // W3C SCXML 4.9: the error ends the block
                }


