extension Engine where Policy == StaticOptionalPolicy {
    /// Raises `due.sent` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
    /// constructed inconsistently (NL-to-IR Item C1 Path A). Both carriers are
    /// filled: the typed one a native expression reads, and `data`, which is what
    /// every other reader of `_event.data` binds it from.
    public func raiseDueSent(due: Int64?, title: String?, status: StaticOptionalStatusEnum?) {
        raiseExternalWithMeta(
            EventWithMetadata(
                StaticOptionalEvent.dueSent,
                metadata: EventMetadata(
                    data: payloadJSON(.raw("due", json: optionalJSON(due) { WireValue.signed64($0).json }), .raw("title", json: optionalJSON(title) { WireValue.text($0).json }), .raw("status", json: optionalJSON(status) { WireValue.text($0.declaredName).json })),
                    eventType: .externalEvent,
                    typedPayload: StaticOptionalDueSentPayload(due: due, title: title, status: status)
                )
            )
        )
    }

    /// Raises `due.set` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
    /// constructed inconsistently (NL-to-IR Item C1 Path A). Both carriers are
    /// filled: the typed one a native expression reads, and `data`, which is what
    /// every other reader of `_event.data` binds it from.
    public func raiseDueSet(id: UInt32, due: Int64?, title: String?, status: StaticOptionalStatusEnum?) {
        raiseExternalWithMeta(
            EventWithMetadata(
                StaticOptionalEvent.dueSet,
                metadata: EventMetadata(
                    data: payloadJSON(.integer("id", id), .raw("due", json: optionalJSON(due) { WireValue.signed64($0).json }), .raw("title", json: optionalJSON(title) { WireValue.text($0).json }), .raw("status", json: optionalJSON(status) { WireValue.text($0.declaredName).json })),
                    eventType: .externalEvent,
                    typedPayload: StaticOptionalDueSetPayload(id: id, due: due, title: title, status: status)
                )
            )
        )
    }
